details:
示例
{
    mixed *elements = ({ "Foo", 42, "Fooville" }) ;
    mixed cl = assemble_class( elements ) ;

    write( sprintf( "%O\n", cl ) ) ;
}

结果：

CLASS( 3 elements
     "Foo",
     42,
     "Fooville"
   )

警告
如果已经定义了一个 class，并把 assemble_class 的结果赋给变量，该变量的结构将由 assemble_class 的结果决定。结构不同不会触发错误，原先的结构声明会被忽略。

   class person {
       string name ;
       int age ;
       string city ;
   }

   void fun()
   {
       class person me ;

       me = assemble_class( ({ "Would", "You", "Like", 42, "Bubblegums" }) ) ;
       write( sprintf( "%O\n", me ) ) ;

       // CLASS( 5 elements
       //   "Would",
       //   "You",
       //   "Like",
       //   42,
       //   "Bubblegums"
       //  )
   }
